package cn.zhuatech.p2p.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service public class InvoiceExceptionService{public Result evaluate(Request r){int score=0;List<String> reasons=new ArrayList<>();if(r.duplicateInvoice()){score+=90;reasons.add("疑似重复发票");}if(r.bankAccountChanged()){score+=45;reasons.add("供应商收款账户发生变更");}if(!r.taxInvoiceValid()){score+=60;reasons.add("税务发票校验未通过");}double variance=r.invoiceAmount().subtract(r.purchaseOrderAmount()).abs().multiply(BigDecimal.valueOf(100)).divide(r.purchaseOrderAmount(),1,RoundingMode.HALF_UP).doubleValue();if(variance>5){score+=35;reasons.add("发票与采购订单金额偏差超过阈值");}if(!r.goodsReceiptConfirmed()){score+=25;reasons.add("收货尚未确认");}if(r.supplierRiskScore()>70)score+=20;score=Math.min(100,score);String status=score>=70?"BLOCK_PAYMENT":score>=25?"REVIEW":"AUTO_APPROVE";if(reasons.isEmpty())reasons.add("付款凭证和匹配条件正常");return new Result(score,variance,status,reasons);}
 public record Request(@NotNull @DecimalMin("0.01") BigDecimal invoiceAmount,@NotNull @DecimalMin("0.01") BigDecimal purchaseOrderAmount,@NotNull Boolean duplicateInvoice,@NotNull Boolean bankAccountChanged,@NotNull Boolean taxInvoiceValid,@NotNull Boolean goodsReceiptConfirmed,@Min(0) @Max(100) int supplierRiskScore){}public record Result(int exceptionScore,double amountVarianceRate,String status,List<String> reasons){} }
